import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Topic — takoform_topic","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/topic/topic.md","filePath":"proposals/topic/topic.md"}'),i={name:"proposals/topic/topic.md"};function s(n,e,c,d,h,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="topic-—-takoform-topic" tabindex="-1">Topic — <code>takoform_topic</code> <a class="header-anchor" href="#topic-—-takoform-topic" aria-label="Permalink to &quot;Topic — `takoform_topic`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A producer publishes one event — an order placed, a file arrived — and every interested consumer receives its own copy through its own subscription without producers knowing who listens. Lifecycle is managed through the provider from birth. Edge workers get a producer binding later (Accepted Bindings below); publishing from non-worker compute families awaits the cross-family projection realization and is not invented here.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The topic has no desired fields: its semantics are entirely fixed by the <code>topic.publish</code> Interface and the <a href="./topic-subscription.html">TopicSubscription</a> attachment.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>Exactly the <code>topic.publish@1.0.0</code> contract: publish one message and fan it out. A message body is a UTF-8 string or the common canonical <code>{&quot;encoding&quot;:&quot;base64&quot;,&quot;data&quot;:&quot;...&quot;}</code> bytes object, plus at most 10 string attributes; body and attributes together are bounded at 262144 bytes — the same message shape the queue family carries, so a delivery fits its target.</p><p>An accepted publish is evaluated against the subscription set as of acceptance: every subscription that exists at that moment and whose filter policy matches the message&#39;s attributes receives its own at-least-once delivery. Deliveries are independent per subscription — one subscription&#39;s failure, retry backlog, or dead-lettering never delays or affects another. A subscription created after acceptance never receives the message. The topic retains nothing and replays nothing: a publish with no subscriptions, or none matching, succeeds and the message is gone. There is no ordering guarantee across or within subscriptions, and at-least-once means a subscription may receive one publish more than once; consumers must be idempotent.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Fanout-without-retention is the contract publishers and subscribers program against. A retention or replay selector would change what a late subscriber can rely on invisibly, and an ordering selector would change consumer correctness requirements — exactly the free semantic tokens decision 0008 prohibits.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A retained, replayable log or stream; an ordered topic; an event bus that routes by rules rather than fanning out to subscriptions. Each changes the delivery model and is a different Form (decision 0043 records <code>eventbus</code> as a deferred family candidate).</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>topic.publish@1.0.0</code> (Interface candidate to be authored with the family&#39;s candidate set).</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None. It is the intended target of a future <code>module-worker.topic</code> producer binding projecting publish into a Worker Version; a binding instance&#39;s <code>resource</code> reference carries an explicit <code>apiVersion</code>, so a cross-family target is representable as-is (<a href="./../../spec/binding-contract/">binding contract</a>).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a topic that any TopicSubscription references, or that a Schedule names as its target, must fail with <code>dependency_in_use</code>. Because nothing is retained, delete destroys no messages — only the fanout point.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The fanout topic offered by every major provider — the &quot;Pub/sub fanout&quot; survey row decision 0043 minted this family from. The withdrawn v1alpha2 epoch had no topic kind (decision 0043&#39;s lineup table records no predecessor); this family is new ground. The Edge family&#39;s push AtLeastOnceQueue is the adjacent contrast: one consumer per queue there, one delivery per subscription here.</p>',20)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
